function updateBinIcons(){const n=binRemaining(),locked=!S.solved.audio;document.querySelectorAll('[data-bin-count]').forEach(x=>{x.textContent=n;x.hidden=!n});document.querySelectorAll('.bin-image').forEach(x=>x.classList.toggle('empty',!n));document.querySelectorAll('.fx-bin-link,[data-id=bin]').forEach(x=>{x.setAttribute('aria-label',`Recycle Bin, ${n} item${n===1?'':'s'}${locked?', locked until Audio Lab is complete':''}`);x.setAttribute('aria-disabled',String(locked));if(x.matches('[data-id=bin]'))x.disabled=locked})}
function setExplorerChrome(e,isBin){if(!e)return;const old=e.querySelector('.wh .title-icon,.wh .bin-title-icon');if(old)old.outerHTML=isBin?binImage(28,'bin-title-icon'):icon('folder','title-icon');e.querySelector('.wh h2').textContent=isBin?'Recycle Bin':'File Explorer';e.setAttribute('aria-label',isBin?`Recycle Bin, ${binRemaining()} items`:'File Explorer')}
function interruptBinScan(message='Scan interrupted. Reconstruction state was reset.'){BIN_SCAN.timers.forEach(clearTimeout);BIN_SCAN.timers=[];if(S.flags.binScan==='scanning'){S.flags.binScan='idle';S.flags.binScanStep=0;S.flags.binScanInterrupted=message;const log=$('#scanlog');if(log)log.innerHTML=`<p class="err">${message}</p>`;save()}}
const screen=id=>{document.querySelectorAll('.scr').forEach(s=>s.hidden=s.id!==id);document.body.classList.toggle('desktop-mode',id==='desktop')};
const rm=()=>document.body.classList.contains('rm')||matchMedia('(prefers-reduced-motion:reduce)').matches;
const pulse=()=>{if(rm())return;document.body.classList.add('pulse');setTimeout(()=>document.body.classList.remove('pulse'),1000)};
const NOTIFICATION_LABELS={system:'NEXUS-7 System',guidance:'Next step',progress:'Progress update',narrative:'System alert'};
const notificationQueue=[];
const visibleNotificationCount=()=> (Array.isArray(S.notes)?S.notes:[]).filter(raw=>{const n=notificationDetails(raw);return !['guidance','narrative'].includes(n.type)||n.requested}).length;
let activeToast=null,notificationTimer=0;
const notificationDetails=n=>typeof n==='string'?{message:n,type:'system',createdAt:0}:{message:String(n?.message||''),type:NOTIFICATION_LABELS[n?.type]?n.type:'system',createdAt:n?.createdAt||0,requested:!!n?.requested};
function showNextNotification(){if(activeToast||!notificationQueue.length)return;const item=notificationQueue.shift(),toast=document.createElement('div'),label=document.createElement('b'),message=document.createElement('span');toast.className=`toast toast-${item.type}`;toast.setAttribute('role','status');label.textContent=NOTIFICATION_LABELS[item.type];message.textContent=item.message;toast.append(label,message);$('#toasts')?.append(toast);activeToast=toast;notificationTimer=setTimeout(()=>{toast.remove();activeToast=null;notificationTimer=0;showNextNotification()},4200)}
const notify=(message,type='system',requested=false)=>{if((type==='guidance'||type==='narrative')&&!requested)return;const item={message:String(message),type:NOTIFICATION_LABELS[type]?type:'system',createdAt:Date.now(),requested:!!requested};S.notes=Array.isArray(S.notes)?S.notes:[];S.notes.push(item);if(S.notes.length>100)S.notes.splice(0,S.notes.length-100);notificationQueue.push(item);const count=$('#belln');if(count)count.textContent=visibleNotificationCount();$('#bell')?.classList.add('lit');save();showNextNotification()};
