function showProgressWizard(){wizard('Resume Mira’s session?',`<p>A recovery checkpoint is saved on this workstation.</p><div class="pending-files"><b>Deletion queue · 3 files pending review</b><ul><li>FINAL_MESS██E.enc · protected archive</li><li>temp_cache.tmp · system cache</li><li>~lock_note.txt · damaged note</li></ul></div><p>The files will remain in the Recycle Bin until recovery is complete.</p><div class="wizard-actions"><button type="button" class="primary" id="wizard-continue-session">Continue</button></div>`);$('#wizard-continue-session').onclick=()=>{finishWizard();toDesktop()}}
