function removeBoardItem(key){const board=boardState();delete board.items[key];board.connections=board.connections.filter(c=>c.a!==key&&c.b!==key);const complete=Object.values(boardMilestones(board)).every(Boolean);board.timelineComplete=complete;S.flags.timelineComplete=complete?1:0;save();refreshBoard();updateWorkflow()}
