function syncEvidenceBoard(){const board=boardState(),known={caesar:['message-time','Mira’s message timestamp','Messages','The handwritten date and the frozen workstation clock place Mira’s message at 03/17 · 00:17.',['meeting']],mailkey:['recording-note','Mira’s recording note','Mail','The recording is named by date: AUD_MMDD.wav. Mira saved it the night of the login, month first.',['audio-reference']],file:['recording-name','Recording filename rebuilt','File Explorer','AUD_0317.wav · The missing month digit is 3.',['filename']],audio:['audio-sequence','Audio sequence recovered','Audio Lab','Four tones appear in bins 4 · 1 · 23 · 14.',['audio-sequence']],enc:['archive-restored','FINAL_MESSAGE.enc restored','Recycle Bin','The archive passed its checksum and was restored to Recovered Files.',['archive']],final:['final-message','Final message decrypted','Terminal','The recovered archive decoded to Mira’s final message.',['final-message']]};let changed=false;for(const key of S.ev){const clue=known[key];if(clue&&!board.items[clue[0]]){const n=Object.keys(board.items).length;board.items[clue[0]]={id:clue[0],title:clue[1],source:clue[2],detail:clue[3],tags:clue[4],kind:'recovered',x:24+(n%3)*230,y:24+Math.floor(n/3)*210,addedAt:Date.now()};changed=true}else if(clue&&JSON.stringify(board.items[clue[0]].tags||[])!==JSON.stringify(clue[4])){board.items[clue[0]].tags=clue[4];changed=true}}if(changed)save()}
function updateWorkflow(){const c=$('#workflow');if(!c||$('#desktop').hidden)return;updateBinIcons();const objective=GAME.objective(S),playable=GAME.OBJECTIVES.filter(x=>x.id!=='login'&&x.id!=='complete'),idx=Math.max(0,playable.findIndex(x=>x.id===objective.id));if(objective.id==='complete'){c.innerHTML='<h2>Recovery complete</h2><p class="flow-count">All investigation acts complete</p><p class="workflow-step">Final choice available</p><p>Review the recovered message and choose what happens to the evidence.</p>';return}c.innerHTML=`<h2>Recovery progress · Act ${objective.act}</h2><p class="flow-count">Step ${idx+1} of ${playable.length} · ${S.ev.length} evidence records</p><p class="workflow-step">Next: ${objective.title}</p><p>${objective.detail.replace('recovered password',passwordLabel())}</p><button type="button" data-workflow-open="${objective.app}">Open ${APPS[objective.app]?.t||objective.title}</button>`;c.querySelector('button').onclick=()=>open(objective.app)}
function ensureSystemState(){if(!Array.isArray(S.logs))S.logs=CONTENT.logs.map((x,i)=>({...x,id:'seed-'+i}));else CONTENT.logs.forEach((x,i)=>{if(!S.logs.some(old=>old.time===x.time&&old.src===x.src&&old.event===x.event))S.logs.push({...x,id:'seed-'+i})});S.termHistory=S.termHistory||[];S.audio=S.audio||{markers:[],captions:true,captionSize:16,visual:false,loop:false,speed:1,preservePitch:true};S.flags=S.flags||{};return S}
