 $('#saveprogress').innerHTML=icon('saveicon')+'<span>Save</span>';$('#saveprogress').onclick=e=>{e.stopPropagation();saveCheckpoint()};$('#resumeprogress').onclick=e=>{e.stopPropagation();resumeCheckpoint()};updateCheckpointUI();
