function ensureGuidancePreferences(){S.guidance={mode:'manual',inactivityMinutes:5,lastActivity:Date.now(),suggestedStage:'',...(S.guidance||{})};return S.guidance}
function notePlayerActivity(){const g=ensureGuidancePreferences();g.lastActivity=Date.now();if(g.suggestedStage!==stage())g.suggestedStage=''}
function offerContextualHint(){const g=ensureGuidancePreferences(),st=stage();if(g.mode==='off'){notify('Contextual hints are disabled in Settings.','system');return}const hints=CONTENT.hints[st]||[];if(!hints.length){notify('This objective is complete; no further hint is needed.','progress');return}const next=GAME.progressiveHint(hints,S.hl[st]||0);modal('Contextual hint',`<p><b>${GAME.objective(S).title}</b></p><p>Hint ${next.level} of ${next.total} for the current objective. Revealing it removes the No Hint badge.</p><button class="btn" id="gh">Reveal hint</button><p id="hh" role="status"></p>`);$('#gh').onclick=()=>{S.hl[st]=(S.hl[st]||0)+1;S.hints++;notePlayerActivity();save();notify(next.text.replaceAll('****',passwordLabel()),'guidance',true);$('#hh').textContent='Hint sent to Notifications.'}}
$('#hintbtn').onclick=offerContextualHint;
function checkHintInactivity(){const g=ensureGuidancePreferences(),st=stage(),delay=g.inactivityMinutes*60000;if($('#desktop').hidden||g.mode!=='suggest'||st==='complete'||Date.now()-g.lastActivity<delay||g.suggestedStage===st)return;g.suggestedStage=st;save();notify(`Still working on “${GAME.objective(S).title}”? Contextual help is available from the ? button.`,'guidance',true)}
['pointerdown','keydown','input'].forEach(type=>document.addEventListener(type,notePlayerActivity,{passive:true}));setInterval(checkHintInactivity,15000);
$('#setbtn').onclick=()=>open('settings');
const resetDialog=$('#reset-confirmation');
$('#reset-game').onclick=()=>resetDialog.showModal();
$('#confirm-reset-game').onclick=async()=>{
 const confirmButton=$('#confirm-reset-game');confirmButton.disabled=true;confirmButton.textContent='Resetting…';
 localStorage.removeItem(STORAGE_KEY);localStorage.removeItem(CHECKPOINT_KEY);localStorage.removeItem('ds');sessionStorage.removeItem('ds_resume_checkpoint');
 try{await fetch(API.save,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({reset:true})})}catch{}
 location.reload();
};
$('#lockbtn').onclick=()=>{
 audioStop();
 Object.values(WM.w).forEach(w=>w.el.remove());
 WM.w={};tb();
 S.solved.login=0;save();
 $('#pw').value='';
 $('#pwmsg').className='';
 $('#pwmsg').textContent='';
 screen('login');
 $('#pw').focus();
};
/* ---- start ---- */
(async()=>{applyAccessibility();try{const r=await fetch(API.content);if(r.ok)Object.assign(CONTENT,await r.json())}catch{}
 // The monitor login is the landing page and must always be the first visible screen.
 if(sessionStorage.getItem('ds_resume_checkpoint')==='1'){sessionStorage.removeItem('ds_resume_checkpoint');S.solved.login=1;toDesktop()}else{S.solved.login=0;boot()}})();
